<?php use App\Core\CSRF; ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Novo atendimento automotivo</h1><p class="text-secondary mb-0">O box é o recurso principal; o profissional é opcional.</p></div><a href="/auto/jobs" class="btn btn-outline-secondary">Ordens</a></div>
<div class="card"><div class="card-body"><form method="post" action="/auto/bookings" class="row g-3" id="auto-internal-book"><?=CSRF::field()?><div class="col-md-4"><label class="form-label">Cliente</label><select name="customer_id" id="ib-customer" class="form-select" required><option value="">Selecione</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Veículo</label><select name="vehicle_id" id="ib-vehicle" class="form-select" required><option value="">Selecione</option><?php foreach($vehicles as $v):?><option value="<?=(int)$v['id']?>" data-customer="<?=(int)$v['customer_id']?>"><?=htmlspecialchars($v['label'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Profissional/equipe (opcional)</label><select name="professional_id" class="form-select"><option value="">Sem atribuição</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Serviço</label><select name="service_id" id="ib-service" class="form-select" required><option value="">Selecione</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?> · R$ <?=number_format((float)$s['price'],2,',','.')?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Data</label><input type="date" id="ib-date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-12"><label class="form-label">Box e horário</label><div id="ib-slots" class="d-flex flex-wrap gap-2"><span class="text-secondary">Escolha serviço e data.</span></div><input type="hidden" name="bay_id" id="ib-bay"><input type="hidden" name="starts_at" id="ib-start"></div><div class="col-12"><label class="form-label">Observações</label><textarea name="notes" class="form-control"></textarea></div><div class="col-12"><button id="ib-submit" class="btn btn-primary" disabled>Criar atendimento</button></div></form></div></div>
<script>(()=>{const c=document.querySelector('#ib-customer'),v=document.querySelector('#ib-vehicle'),s=document.querySelector('#ib-service'),d=document.querySelector('#ib-date'),box=document.querySelector('#ib-slots'),bay=document.querySelector('#ib-bay'),start=document.querySelector('#ib-start'),submit=document.querySelector('#ib-submit');function filterVehicle(){[...v.options].forEach((o,i)=>{if(i===0)return;o.hidden=c.value&&o.dataset.customer!==c.value});if(v.selectedOptions[0]?.hidden)v.value=''}async function load(){bay.value='';start.value='';submit.disabled=true;if(!s.value||!d.value){box.innerHTML='<span class="text-secondary">Escolha serviço e data.</span>';return}box.innerHTML='Buscando...';const r=await fetch('/auto/bookings/availability?service_id='+encodeURIComponent(s.value)+'&date='+encodeURIComponent(d.value));const data=await r.json();box.innerHTML='';if(!data.slots?.length){box.innerHTML='<div class="alert alert-warning w-100 mb-0">Sem disponibilidade.</div>';return}data.slots.forEach(x=>{const b=document.createElement('button');b.type='button';b.className='btn btn-outline-primary';b.textContent=x.time+' · '+x.bay_name;b.onclick=()=>{[...box.querySelectorAll('button')].forEach(y=>{y.classList.remove('btn-primary');y.classList.add('btn-outline-primary')});b.classList.remove('btn-outline-primary');b.classList.add('btn-primary');bay.value=x.bay_id;start.value=x.starts_at;submit.disabled=false};box.appendChild(b)})}c.addEventListener('change',filterVehicle);s.addEventListener('change',load);d.addEventListener('change',load);filterVehicle()})();</script>
